head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[multiselect > M > getItemCount]<br/>Multiselect 컴포넌트에 정의된 전체 아이템의 개수를 반환합니다.",
    "validation" : [
        "Multiselect 컴포넌트에 정의된 전체 아이템의 개수를 Number 타입으로 반환합니다.",
        "아이템이 존재하지 않으면 0 을 반환합니다.",
        "선택된 아이템의 개수가 아닌 전체 아이템의 개수를 반환합니다.",
        "addItem 으로 아이템을 추가하면 getItemCount 의 반환값이 1 증가합니다.",
        "deleteItem 으로 아이템을 제거하면 getItemCount 의 반환값이 1 감소합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (BindItemSet: gdl_multiselect 와 바인딩, 기본 3개 아이템)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // gdl_multiselect 재생성 (idempotent: 기존 dataList 제거 후 재생성)
    $c.gcm.createDataListMultiSelect();

    // comp 생성 함수 호출 (기본 3개 아이템: multiselect1/2/3)
    $c.gcm.createBasicMultiSelect();
}



// getItemCount 메소드 호출 (전체 아이템 개수 반환)
scwin.btn_getItemCount_onclick = function (e) {
    let cnt = target1.getItemCount();
    wf_body_bottom.getObj("scwin").setReturnValue("getItemCount : " + cnt);
    wf_body_bottom.getObj("scwin").setReturnValue("typeof : " + (typeof cnt));
};



// addItem 후 getItemCount 변화 확인 (1 증가)
scwin.btn_addItem_onclick = function (e) {
    let beforeCnt = target1.getItemCount();
    let value = par_value.getValue();
    let label = par_label.getValue();
    target1.addItem(value, label);
    let afterCnt = target1.getItemCount();

    wf_body_bottom.getObj("scwin").setReturnValue("addItem 전 getItemCount : " + beforeCnt);
    wf_body_bottom.getObj("scwin").setReturnValue("addItem 후 getItemCount : " + afterCnt);
    wf_body_bottom.getObj("scwin").setReturnValue("증가량 : " + (afterCnt - beforeCnt));
};



// deleteItem 후 getItemCount 변화 확인 (1 감소)
// BindItemSet 모드에서 deleteItem 은 1-based 인덱스 + refresh=true 명시 필수 (DataCollection 반영)
scwin.btn_deleteItem_onclick = function (e) {
    let beforeCnt = target1.getItemCount();
    if (beforeCnt <= 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("아이템이 없어 삭제할 수 없습니다. getItemCount : " + beforeCnt);
        return;
    }
    target1.deleteItem(1, true);
    let afterCnt = target1.getItemCount();

    wf_body_bottom.getObj("scwin").setReturnValue("deleteItem 전 getItemCount : " + beforeCnt);
    wf_body_bottom.getObj("scwin").setReturnValue("deleteItem 후 getItemCount : " + afterCnt);
    wf_body_bottom.getObj("scwin").setReturnValue("감소량 : " + (beforeCnt - afterCnt));
};



// 모든 아이템 제거 후 getItemCount 가 0 을 반환하는지 확인
// BindItemSet 모드에서는 dataList 를 직접 비워야 정상 동작
scwin.btn_deleteAll_onclick = function (e) {
    gdl_multiselect.removeAll();
    wf_body_bottom.getObj("scwin").setReturnValue("모든 아이템 제거 후 getItemCount : " + target1.getItemCount());
};



// 첫번째 아이템 선택 후, 선택된 개수와 전체 개수 비교
// (선택 후에도 getItemCount 는 전체 개수를 반환함을 확인)
scwin.btn_selectItem_onclick = function (e) {
    let totalCnt = target1.getItemCount();
    if (totalCnt <= 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("선택할 아이템이 없습니다. getItemCount : " + totalCnt);
        return;
    }
    target1.setSelectedIndex([0], true);
    let selectedArr = target1.getSelectedIndex();
    let selectedCnt = (selectedArr || []).length;

    wf_body_bottom.getObj("scwin").setReturnValue("getItemCount (전체 개수) : " + target1.getItemCount());
    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex.length (선택 개수) : " + selectedCnt);
};
